  List<String> fetchBingSuggestions(String query){ArrayList<String> out=new ArrayList<>();HttpURLConnection c=null;try{String url="https://www.bing.com/osjson.aspx?query="+URLEncoder.encode(query,"UTF-8");c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(2500);c.setReadTimeout(3500);c.setRequestProperty("User-Agent","Mozilla/5.0");String body=read(c);JSONArray root=new JSONArray(body),values=root.optJSONArray(1);if(values!=null)for(int i=0;i<values.length()&&out.size()<8;i++){String s=values.optString(i).trim();if(!s.isEmpty())out.add(s);}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}return out;}
  String read(HttpURLConnection c)throws Exception{try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];for(int n;(n=in.read(b))>0&&out.size()<256*1024;)out.write(b,0,n);return out.toString("UTF-8");}}
