  void hideSuggestions(){final int closing=++suggestionGeneration;if(suggestionInput!=null){suggestionInput.clearFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(suggestionInput.getWindowToken(),0);}if(suggestionLayer.getVisibility()!=View.VISIBLE){suggestionLayer.removeAllViews();suggestionInput=null;suggestionResults=null;return;}suggestionLayer.animate().cancel();Runnable finish=()->{if(closing!=suggestionGeneration)return;suggestionLayer.removeAllViews();suggestionLayer.setVisibility(View.GONE);suggestionLayer.setAlpha(1f);suggestionLayer.setTranslationY(0f);suggestionInput=null;suggestionResults=null;};if(!motionEnabled()){finish.run();return;}suggestionLayer.animate().alpha(0f).translationY(dp(18)).setDuration(150).withEndAction(finish).start();}


  boolean handleNavigation(WebView view,String raw){String value=raw==null?"":raw.trim();if(value.isEmpty())return false;Uri uri;try{uri=Uri.parse(value);}catch(Exception ignored){return false;}String scheme=uri.getScheme();if(scheme==null||scheme.equalsIgnoreCase("http")||scheme.equalsIgnoreCase("https"))return false;if(scheme.equalsIgnoreCase("intent")){Intent external;try{external=Intent.parseUri(value,Intent.URI_INTENT_SCHEME);}catch(Exception error){notice("无法解析应用跳转",false);return true;}String fallback=webFallback(external);sanitizeExternalIntent(external);confirmExternal(external,fallback);return true;}Intent external=new Intent(Intent.ACTION_VIEW,uri);external.addCategory(Intent.CATEGORY_BROWSABLE);external.setFlags(0);confirmExternal(external,nestedWebUrl(uri));return true;}
  void confirmExternal(Intent external,String fallback){String label=external.getData()==null?"外部应用":external.getData().toString();LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(12),dp(20),dp(8));TextView note=text("网页请求打开外部应用：\n"+label,13,TEXT);note.setMaxLines(4);panel.addView(note,new LinearLayout.LayoutParams(-1,-2));AlertDialog d=new AlertDialog.Builder(this).setTitle("是否离开内置网页？").setView(panel).setNegativeButton("取消",null).setNeutralButton(fallback==null||fallback.isEmpty()?"留在网页":"打开网页备用链接",(x,w)->{if(fallback!=null&&!fallback.isEmpty())web.loadUrl(fallback);}).setPositiveButton("允许打开",(x,w)->{try{startActivity(external);}catch(Exception error){if(fallback!=null&&!fallback.isEmpty())web.loadUrl(fallback);else notice("未找到可处理此跳转的应用",true);}}).create();showRounded(d);}
  void sanitizeExternalIntent(Intent intent){intent.setAction(Intent.ACTION_VIEW);intent.addCategory(Intent.CATEGORY_BROWSABLE);intent.setComponent(null);intent.setSelector(null);intent.setFlags(0);intent.removeExtra("browser_fallback_url");}
  String webFallback(Intent intent){String fallback=intent==null?"":safeWebUrl(intent.getStringExtra("browser_fallback_url"));if(!fallback.isEmpty())return fallback;return intent==null?"":nestedWebUrl(intent.getData());}
  String nestedWebUrl(Uri uri){if(uri==null)return"";try{for(String name:uri.getQueryParameterNames()){String candidate=safeWebUrl(uri.getQueryParameter(name));if(!candidate.isEmpty())return candidate;}}catch(Exception ignored){}return"";}
  String safeWebUrl(String raw){if(raw==null)return"";String value=raw.trim();try{Uri uri=Uri.parse(value);String scheme=uri.getScheme();return scheme!=null&&(scheme.equalsIgnoreCase("http")||scheme.equalsIgnoreCase("https"))?value:"";}catch(Exception ignored){return"";}}

    boolean isSearchInput(String raw){String v=raw==null?"":raw.trim();if(v.isEmpty())return false;try{Uri parsed=Uri.parse(v);String scheme=parsed.getScheme();if(scheme!=null&&(scheme.equalsIgnoreCase("http")||scheme.equalsIgnoreCase("https")))return false;}catch(Exception ignored){}return v.contains(" ")||!v.matches("(?i)(?:localhost|(?:[a-z0-9-]+\\.)+[a-z]{2,})(?:[:/].*)?");}
  void saveSearchQuery(String raw){String value=raw==null?"":raw.trim();if(value.isEmpty())return;searchQueries.removeIf(x->x.equalsIgnoreCase(value));searchQueries.add(0,value);while(searchQueries.size()>MAX_SEARCH_HISTORY)searchQueries.remove(searchQueries.size()-1);saveState();}
  void navigateInput(String raw){String value=raw==null?"":raw.trim();if(isSearchInput(value))saveSearchQuery(value);hideSuggestions();address.clearFocus();String target=resolveInput(value);load(target);}

  String resolveInput(String raw){String v=raw==null?"":raw.trim();if(v.isEmpty())return"https://www.bing.com/";try{Uri parsed=Uri.parse(v);String scheme=parsed.getScheme();if(scheme!=null&&(scheme.equalsIgnoreCase("http")||scheme.equalsIgnoreCase("https")))return v;}catch(Exception ignored){}if(!v.contains(" ")&&v.matches("(?i)(?:localhost|(?:[a-z0-9-]+\\.)+[a-z]{2,})(?:[:/].*)?"))return"https://"+v;try{return"https://www.bing.com/search?q="+URLEncoder.encode(v,"UTF-8");}catch(Exception ignored){return"https://www.bing.com/";}}
  void load(String raw){String u=resolveInput(raw);currentUrl=u;setAddress(u,false);web.loadUrl(u);}
