  void pushHistory(String title,String url){if(url==null||url.isEmpty()||url.startsWith("about:"))return;history.removeIf(e->e.url.equals(url));history.add(0,new Entry(title,url,System.currentTimeMillis()));while(history.size()>MAX_HISTORY)history.remove(history.size()-1);saveState();}
  void upsert(List<Entry> list,Entry e){list.removeIf(x->x.url.equals(e.url));list.add(0,e);while(list.size()>MAX_HISTORY)list.remove(list.size()-1);}
    void loadState(){history.clear();favorites.clear();searchQueries.clear();android.content.SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);readEntries(p.getString(HISTORY,"[]"),history);readEntries(p.getString(FAVORITES,"[]"),favorites);readQueries(p.getString(SEARCH_HISTORY,"[]"),searchQueries);}

    void saveState(){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString(HISTORY,writeEntries(history)).putString(FAVORITES,writeEntries(favorites)).putString(SEARCH_HISTORY,writeQueries(searchQueries)).apply();}

  void readEntries(String raw,List<Entry> out){try{JSONArray a=new JSONArray(raw);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String u=o.optString("u");if(!u.isEmpty())out.add(new Entry(o.optString("t",u),u,o.optLong("a")));}}catch(Exception ignored){}}
    String writeEntries(List<Entry> values){JSONArray a=new JSONArray();for(Entry e:values)try{a.put(new JSONObject().put("t",e.title).put("u",e.url).put("a",e.at));}catch(Exception ignored){}return a.toString();}
  void readQueries(String raw,List<String> out){try{JSONArray a=new JSONArray(raw);for(int i=0;i<a.length()&&out.size()<MAX_SEARCH_HISTORY;i++){String value=a.optString(i).trim();if(!value.isEmpty()&&!out.contains(value))out.add(value);}}catch(Exception ignored){}}
  String writeQueries(List<String> values){JSONArray a=new JSONArray();for(int i=0;i<Math.min(MAX_SEARCH_HISTORY,values.size());i++)a.put(values.get(i));return a.toString();}


  void download(String u,String d,String m,long z){String name=fileName(u,d,m);notice("已加入下载："+name,false);if(MainActivity.enqueueWebDownload(u,name))return;Intent i=new Intent(this,MainActivity.class).setAction(MainActivity.ACTION_WEB_DOWNLOAD).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);i.putExtra("url",u);i.putExtra("name",name);startActivity(i);}
  String fileName(String u,String d,String m){String name=contentDispositionName(d);if(name.isEmpty())name=URLUtil.guessFileName(u,d,m);name=cleanFileName(name.isEmpty()?"download":name);String mime=m==null?"":m.split(";",2)[0].trim().toLowerCase(java.util.Locale.ROOT),wanted=MainActivity.extensionForMime(mime),current=MainActivity.fileNameExtension(name);if(!wanted.isEmpty()&&(current.isEmpty()||current.equals("bin")||current.equals("dat")||current.equals("tmp")))name=MainActivity.replaceOrAppendExtension(name,wanted);return name;}
  String contentDispositionName(String d){if(d==null)return"";String value=d.trim();Matcher star=Pattern.compile("(?i)filename[*][ \\t]*=[ \\t]*(?:UTF-8''|utf-8'')?([^;]+)").matcher(value);if(star.find())return decodeName(star.group(1));Matcher normal=Pattern.compile("(?i)filename[ \\t]*=[ \\t]*(?:\"([^\"]+)\"|([^;]+))").matcher(value);if(normal.find())return decodeName(normal.group(1)!=null?normal.group(1):normal.group(2));return"";}
  String decodeName(String raw){try{return URLDecoder.decode(raw.replaceAll("^[\"']|[\"']$","").trim(),"UTF-8");}catch(Exception ignored){return raw==null?"":raw.trim();}}
  String cleanFileName(String raw){String value=raw==null?"":raw.trim();value=value.replaceAll("[\\\\/:*?\"<>|\\r\\n]+","_");return value.isEmpty()?"download":value;}

